**Transport Management System Overview**
======================================

This C# implementation showcases a multi-threaded Transport Management System, comprising three isolated modules:

1.  **Fleet Telemetry Tracker**: responsible for collecting GPS data and detecting speed anomalies.
2.  **Route Optimization Engine**: utilizes Dijkstra's algorithm to determine the most efficient routes, considering live traffic conditions.
3.  **Automated Billing & Invoicing Subsystem**: calculates dynamic tolls based on route and vehicle information.

**Module 1: Fleet Telemetry Tracker**
-----------------------------------

```csharp
using System;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;

public class FleetTelemetryTracker
{
    private readonly Dictionary<string, Vehicle> _vehicles;
    private readonly CancellationTokenSource _cts;

    public FleetTelemetryTracker()
    {
        _vehicles = new Dictionary<string, Vehicle>();
        _cts = new CancellationTokenSource();
    }

    // Register a vehicle with its ID and initial location
    public void RegisterVehicle(string vehicleId, Location location)
    {
        _vehicles[vehicleId] = new Vehicle(vehicleId, location);
    }

    // Start tracking GPS data for all vehicles
    public async Task StartTrackingAsync()
    {
        while (!_cts.IsCancellationRequested)
        {
            foreach (var vehicle in _vehicles.Values)
            {
                // Simulate GPS data retrieval (e.g., from a database or API)
                var newLocation = GetNewLocation(vehicle);
                vehicle.UpdateLocation(newLocation);

                // Detect speed anomalies
                DetectAnomalies(vehicle);
            }

            await Task.Delay(1000, _cts.Token); // 1-second interval
        }
    }

    // Update a vehicle's location and detect speed anomalies
    private Location GetNewLocation(Vehicle vehicle)
    {
        // Simulate new GPS location (e.g., from a database or API)
        return new Location(vehicle.Location.Longitude + 0.001, vehicle.Location.Latitude + 0.001);
    }

    private void DetectAnomalies(Vehicle vehicle)
    {
        // Basic speed anomaly detection (for demonstration purposes only)
        var speed = CalculateSpeed(vehicle);
        if (speed > 120) // Speed limit (km/h)
        {
            Console.WriteLine($"Speed anomaly detected for vehicle {vehicle.Id}: {speed} km/h");
        }
    }

    // Calculate the speed of a vehicle
    private double CalculateSpeed(Vehicle vehicle)
    {
        var distance = CalculateDistance(vehicle.PreviousLocation, vehicle.Location);
        var timeElapsed = 1; // 1-second interval
        return distance / timeElapsed * 3.6; // Convert meters to kilometers per hour
    }

    // Calculate the distance between two locations
    private double CalculateDistance(Location loc1, Location loc2)
    {
        var lon1 = loc1.Longitude * Math.PI / 180;
        var lat1 = loc1.Latitude * Math.PI / 180;
        var lon2 = loc2.Longitude * Math.PI / 180;
        var lat2 = loc2.Latitude * Math.PI / 180;

        var dlon = lon2 - lon1;
        var dlat = lat2 - lat1;

        var a = Math.Pow(Math.Sin(dlat / 2), 2) + Math.Cos(lat1) * Math.Cos(lat2) * Math.Pow(Math.Sin(dlon / 2), 2);
        var c = 2 * Math.Atan2(Math.Sqrt(a), Math.Sqrt(1 - a));
        var R = 6371; // Earth's radius in kilometers

        return R * c * 1000; // Convert kilometers to meters
    }
}

public class Vehicle
{
    public string Id { get; }
    public Location Location { get; private set; }
    public Location PreviousLocation { get; private set; }

    public Vehicle(string id, Location location)
    {
        Id = id;
        Location = location;
    }

    public void UpdateLocation(Location newLocation)
    {
        PreviousLocation = Location;
        Location = newLocation;
    }
}

public struct Location
{
    public double Longitude { get; }
    public double Latitude { get; }

    public Location(double longitude, double latitude)
    {
        Longitude = longitude;
        Latitude = latitude;
    }
}
```

**Module 2: Route Optimization Engine**
--------------------------------------

```csharp
using System;
using System.Collections.Generic;
using System.Linq;

public class RouteOptimizationEngine
{
    // Dijkstra's algorithm implementation for route optimization
    public RouteOptimizeResponse OptimizeRoute(Location start, Location end, Dictionary<Location, Dictionary<Location, int>> graph)
    {
        var shortestDistances = new Dictionary<Location, int>();
        var predecessors = new Dictionary<Location, Location>();
        var unseenNodes = new List<Location>(graph.Keys);
        var infinity = int.MaxValue;
        var path = new List<Location>();

        foreach (var node in unseenNodes)
        {
            shortestDistances[node] = infinity;
        }

        shortestDistances[start] = 0;

        while (unseenNodes.Count > 0)
        {
            var currentNode = GetLowestDistanceNode(unseenNodes, shortestDistances);

            unseenNodes.Remove(currentNode);

            var neighbors = graph[currentNode];

            foreach (var neighbor in neighbors)
            {
                var weight = neighbor.Value;
                if (weight + shortestDistances[currentNode] < shortestDistances[neighbor.Key])
                {
                    shortestDistances[neighbor.Key] = weight + shortestDistances[currentNode];
                    predecessors[neighbor.Key] = currentNode;
                }
            }
        }

        var longestDistanceNode = end;
        while (longestDistanceNode != null)
        {
            path.Add(longestDistanceNode);
            longestDistanceNode = predecessors.ContainsKey(longestDistanceNode) ? predecessors[longestDistanceNode] : null;
        }

        path.Reverse();

        return new RouteOptimizeResponse(path, shortestDistances[end]);
    }

    private Location GetLowestDistanceNode(List<Location> unseenNodes, Dictionary<Location, int> shortestDistances)
    {
        return unseenNodes.OrderBy(n => shortestDistances[n]).First();
    }
}

public class RouteOptimizeResponse
{
    public List<Location> Path { get; }
    public int Distance { get; }

    public RouteOptimizeResponse(List<Location> path, int distance)
    {
        Path = path;
        Distance = distance;
    }
}

public class LiveTrafficUpdater
{
    public void UpdateLiveTraffic(Dictionary<Location, Dictionary<Location, int>> graph)
    {
        // Simulate live traffic data updates (e.g., from a database or API)
        foreach (var node in graph)
        {
            foreach (var neighbor in node.Value)
            {
                // Simulate dynamic weight updates
                neighbor.Value = (int)(neighbor.Value * (1 + new Random().NextDouble() / 10)); // 10% random variation
            }
        }
    }
}
