```csharp
using System;
using System.Collections.Generic;

public class AutomatedBillingSystem
{
    public void CalculateDynamicTolls(List<Location> path, Dictionary<Location, Dictionary<Location, int>> graph)
    {
        var tolls = new List<Toll>();

        for (var i = 0; i < path.Count - 1; i++)
        {
            var toll = new Toll(path[i], path[i + 1], graph[path[i]][path[i + 1]]);
            tolls.Add(toll);
        }

        Console.WriteLine("Calculated Dynamic Tolls:");
        foreach (var toll in tolls)
        {
            Console.WriteLine($"{toll.StartLocation} -> {toll.EndLocation}: ${toll.CalculateToll()}");
        }
    }
}

public class Toll
{
    public Location StartLocation { get; }
    public Location EndLocation { get; }
    public int Distance { get; }

    public Toll(Location startLocation, Location endLocation, int distance)
    {
        StartLocation = startLocation;
        EndLocation = endLocation;
        Distance = distance;
    }

    public double CalculateToll()
    {
        // Simulate toll calculation based on distance and vehicle type
        return Distance * 0.05;
    }
}
```

